data: {"index":1,"delta":{"text":" peppers, and cucumbers need full sun.\n*   **Water Access:** Ensure your garden is close to a water source.","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" Dragging a heavy hose across the yard every day becomes tedious quickly and might discourage you from watering consistently.\n*   **Drain","type":"text"},"event_type":"step.delta"}

